export const routingCases = [];
for (const [expectedGuide, inputs] of Object.entries(guidePhrases)) {
  for (const input of inputs) {
    const normalized = input.toLowerCase();
    const tags = [];
    if (/^(hallo|hi|servus|guten)/i.test(input)) tags.push('greeting');
    if (/berict|viste|durchfurung|hinzufuegen|massnahme/i.test(normalized)) tags.push('asr-or-typo');
    routingCases.push({ input, expectedKind: 'guide', expectedGuide, tags });
  }
}
